package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Refuses any change by a viewer, and any change at all on an archived sheet, before anything is
 * read or written. A viewer sees every screen and figure and can change nothing; an archived sheet
 * stays visible to everyone and no one can change it. Runs first on every change endpoint except the
 * bulk ones, which go through with every selected item refused.
 */
public class CheckCanChange {
    public void check(@PathVariable("sheetId") String sheetId, RoleRepository roles, SheetRepository sheets,
            HttpServletRequest request) throws ViewerException, SheetArchivedException {
        String id = sheetId == null ? "" : sheetId.trim();
        String user = Audit.user(request);
        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
            throw new ViewerException("A viewer may not change the sheet");
        }
        if (sheets.isArchived(id)) throw new SheetArchivedException(id);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.AsOf;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Loads the sheet. A read made as of a date (see {@link AsOf}) loads it as it stood at the end of
 * that date, the date standing in for its today; a change always loads it as it is now.
 */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository,
            HttpServletRequest request, Out<Sheet> sheetOut) throws SheetNotFoundException {
        Sheet sheet = repository.find(sheetId == null ? "" : sheetId.trim());
        if (sheet == null) throw new SheetNotFoundException(sheetId);
        LocalDate asOf = "GET".equals(request.getMethod()) ? AsOf.of(request) : null;
        sheetOut.set(asOf == null ? sheet : repository.asOf(sheet, asOf));
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

/**
 * The as-of date the signed-in user's screen reads the sheet at, named on each read in the
 * {@code X-As-Of} header (yyyy-MM-dd). While it is set, a read answers with the sheet as it stood at
 * the end of that date: every change made while the sheet's today was on or before it, and that
 * date standing in for the sheet's today. Changes never carry it.
 */
public final class AsOf {

    public static final String HEADER = "X-As-Of";

    private AsOf() {
    }

    /** The as-of date the request reads at, or null when it reads the sheet as it is now. */
    public static LocalDate of(HttpServletRequest request) {
        String raw = request == null ? null : request.getHeader(HEADER);
        if (raw == null || raw.isBlank()) return null;
        try {
            return LocalDate.parse(raw.trim());
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/**
 * A claim, as the screen reads it: its amount with two decimals, its date as yyyy-MM-dd and its
 * status, its number ("" when it has none), and its due as fixed when it was settled ("" while
 * its due is live), and who opened it ("" until it is opened); whether its person's last
 * statement bound it, and the figure it was bound to ("" when not stated, n/a when it had none);
 * and the number of the claim it corrects ("" when it is no correction); and the date its figures
 * round by (a correction's is the date of the claim it corrects); and its due-by as yyyy-MM-dd, fixed
 * when it was made; and its status log, oldest first, one line per status it has had as
 * {@code <STATUS> by <user> on <date> due=<due>}; and the date it is deferred until as yyyy-MM-dd
 * ("" when it was never deferred; it is deferred only while OPEN and the sheet's today is before it);
 * and how many proofs it has had added; and the number of the claim it was split off ("" when none);
 * and the user whose open editor locks it on the sheet's today ("" when no one's does);
 * and whether it was added while its period was soft-closed; and the last sheet's today it was reminded
 * as yyyy-MM-dd ("" when never); and its external reference ("" when none); and its tags, sorted (none: empty); and the reason it was voided with ("" when none).
 */
public record ClaimResponse(String id, String personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated,
        String statedDue, String corrects, String roundDate, String dueBy, List<String> log, String deferredUntil,
        int proofs, String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref,
        List<String> tags, String voidReason) {
    public static ClaimResponse from(Claim claim) {
        return from(claim, List.of());
    }

    public static ClaimResponse from(Claim claim, List<String> log) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(),
                claim.getNumber() == null ? "" : claim.getNumber(),
                claim.getSettledDue() == null ? "" : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(),
                claim.isStated(),
                !claim.isStated() ? "" : claim.getStatedDue() == null ? "n/a" : claim.getStatedDue().toPlainString(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundDate().toString(), claim.getDueBy().toString(), log,
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                claim.getProofs(),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(),
                claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef(),
                claim.tagList(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason());
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** The claims on a sheet, newest first, and every tag ever used on it, sorted. */
public record ClaimsResponse(List<ClaimResponse> claims, List<String> tags) {
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's claims, newest first, and the tags ever used on it; read as of a date, as they stood then. */
public class RespondWithClaims {
    public void respond(@Val Sheet sheet, ClaimRepository repository, ClaimLogRepository log,
            HttpServletRequest request, ObjectResponse<ClaimsResponse> response) {
        LocalDate asOf = AsOf.of(request);
        Map<Long, List<String>> logs = asOf == null ? log.findAll(sheet.id()) : log.findAllOn(sheet.id(), asOf);
        List<Claim> claims = asOf == null ? repository.findAll(sheet.id()) : repository.findAllAsOf(sheet.id(), asOf);
        response.send(new ClaimsResponse(claims.stream()
                .map((claim) -> ClaimResponse.from(claim, logs.getOrDefault(claim.getId(), List.of()))).toList(),
                repository.tagsUsed(sheet.id(), asOf)));
    }
}
# The claims on a sheet, newest first.
